 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    return comps


def _elbows(cells):
    """Return (corner row/col, horizontal endpoint col) for an L object."""
    rows = {r for r, _ in cells}
    cols = {c for _, c in cells}
    for r in rows:
        for c in cols:
            horizontal = {x for y, x in cells if y == r}
            vertical = {y for y, x in cells if x == c}
            if (len(horizontal) >= 3 and len(vertical) >= 3 and
                    len(horizontal) + len(vertical) - 1 == len(cells) and
                    all(y == r or x == c for y, x in cells)):
                endpoint = min(horizontal) if min(horizontal) != c else max(horizontal)
                return r, c, endpoint
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    guides = []
    for color, cells in comps:
        elbow = _elbows(cells)
        if elbow is not None:
            guides.append((color, cells, elbow))
    if not guides:
        return [row[:] for row in grid]

    # The L's horizontal free endpoint marks a column containing the object
    # to recolor with the L's color.
    guide_color, guide_cells, (_, _, endpoint_col) = max(guides, key=lambda x: len(x[1]))
    targets = [(color, cells) for color, cells in comps
               if cells != guide_cells and any(c == endpoint_col for _, c in cells)]
    if not targets:
        return [row[:] for row in grid]
    # If several objects lie on that column, the nearest to the guide endpoint
    # is the one indicated.
    target_color, target_cells = min(
        targets,
        key=lambda item: min(abs(r - min((y for y, x in guide_cells if x == endpoint_col)))
                             for r, c in item[1] if c == endpoint_col)
    )
    out = [row[:] for row in grid]
    for r, c in target_cells:
        out[r][c] = guide_color
    return out


